const D = { density: .5, energy: .6, speed: 1, scale: 1, hue: 200, x: .5, y: .5, style: 'circuit', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const u = Math.min(width, height);
const clp = (v,a,b)=>Math.max(a,Math.min(b,v));
const intn = (K.intensity!=null?K.intensity:.6);
const AL = clp(P.alpha,0,100)/100;
const style = P.style;
const glowStyle = (style==='circuit'||style==='hedge'||style==='dungeon');
const hue = ((P.hue%360)+360)%360;

// ---- grid dims from density (rebuild-triggering) ----
const pitchFrac = 0.112 - clp(P.density,0,1)*0.070;
const cols = clp(Math.round(width/(u*pitchFrac)), 5, 54);
const rows = clp(Math.round(height/(u*pitchFrac)), 5, 40);
const N = cols*rows;

// ---- buffer (size-keyed) ----
const sizeKey = width+'x'+height;
if (!S.buf || S.sizeKey!==sizeKey){ if(S.buf&&S.buf.remove)S.buf.remove(); S.buf=createGraphics(width,height); S.buf.colorMode(HSB,360,100,100,100); S.buf.pixelDensity(1); S.sizeKey=sizeKey; S.mazeKey=null; }
if (S.seedUsed!==P.seed){ S.seedUsed=P.seed; S.epoch=0; S.mazeKey=null; }

const cw = width/cols, ch = height/rows, pit = Math.min(cw,ch);
const centerX = c => ((c%cols)+0.5)*cw;
const centerY = c => (((c/cols)|0)+0.5)*ch;

// ground rep color (for dissolve wash)
const gCol = style==='blueprint'?[212,65,30]:style==='thread'?[38,12,80]:style==='hedge'?[120,45,26]:style==='dungeon'?[28,18,15]:[hue,58,10];

function paintGround(){
  const g=S.buf, ctx=g.drawingContext;
  g.push();
  if(style==='blueprint'){
    g.background(212,65,30);
    g.stroke(205,25,60,45); g.strokeWeight(1);
    for(let x=0;x<=cols;x++) g.line(x*cw,0,x*cw,height);
    for(let y=0;y<=rows;y++) g.line(0,y*ch,width,y*ch);
  } else if(style==='thread'){
    g.background(38,12,80); g.noStroke();
    for(let i=0;i<N;i++){ g.fill(34,14,64,26); g.circle(centerX(i),centerY(i),pit*0.05); }
  } else if(style==='hedge'){
    g.background(122,48,24); g.noStroke();
    const nd=Math.min(1100, N*2);
    for(let i=0;i<nd;i++){ const rx=S.rnd()*width, ry=S.rnd()*height, sh=S.rnd(); g.fill(108+sh*30, 40+sh*35, 18+sh*26, 60); g.circle(rx,ry, pit*(0.18+sh*0.35)); }
  } else if(style==='dungeon'){
    g.background(28,18,15); g.noStroke();
    const nd=Math.min(1200, N*2);
    for(let i=0;i<nd;i++){ const rx=S.rnd()*width, ry=S.rnd()*height, sh=S.rnd(); g.fill(26+sh*14, 10+sh*18, 8+sh*22, 40); g.circle(rx,ry, pit*(0.15+sh*0.3)); }
  } else { // circuit vignette
    const gr=ctx.createRadialGradient(width*0.5,height*0.5,0, width*0.5,height*0.5, Math.max(width,height)*0.72);
    gr.addColorStop(0,'hsl('+hue+',62%,17%)'); gr.addColorStop(1,'hsl('+((hue+18)%360)+',72%,7%)');
    ctx.fillStyle=gr; ctx.fillRect(0,0,width,height);
    g.noStroke();
    for(let i=0;i<N;i++){ g.fill(hue,45,24,80); g.circle(centerX(i),centerY(i),pit*0.06); }
  }
  g.pop();
}

function initMaze(){
  let z=((P.seed*2654435761)^(((S.epoch|0))*40503)^0x9e3779b1)>>>0;
  S.rnd=()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.vis=new Uint8Array(N); S.par=new Int32Array(N).fill(-1);
  paintGround();
  const sx=clp(Math.round(clp(P.x,0.06,0.94)*(cols-1)),0,cols-1);
  const sy=clp(Math.round(clp(P.y,0.06,0.94)*(rows-1)),0,rows-1);
  const start=sy*cols+sx;
  S.vis[start]=1; S.stack=[start];
  S.entrance = clp(Math.round(clp(P.x,0.06,0.94)*(cols-1)),0,cols-1);
  S.exit = (rows-1)*cols + clp(Math.round((1-clp(P.x,0.06,0.94))*(cols-1)),0,cols-1);
  S.phase='carve'; S.sol=null; S.solveT=0; S.dissT=0; S.holdStart=null;
}

const mazeKey = cols+'|'+rows+'|'+P.seed+'|'+(S.epoch|0)+'|'+style;
if (S.mazeKey!==mazeKey){ S.mazeKey=mazeKey; initMaze(); }

function stampPassage(a,b){
  const g=S.buf, ctx=g.drawingContext;
  const ax=centerX(a),ay=centerY(a),bx=centerX(b),by=centerY(b);
  const rw=pit*clp(0.30+P.scale*0.14,0.2,0.6);
  g.push(); g.strokeCap(ROUND); g.strokeJoin(ROUND); g.noFill();
  if(style==='circuit'){
    ctx.shadowBlur=9*(0.4+P.energy); ctx.shadowColor='hsla('+hue+',85%,55%,0.9)';
    g.stroke(hue,72,88); g.strokeWeight(rw*0.62); g.line(ax,ay,bx,by);
    ctx.shadowBlur=0;
    g.stroke((hue+8)%360,22,100); g.strokeWeight(rw*0.24); g.line(ax,ay,bx,by);
  } else if(style==='blueprint'){
    g.stroke(205,10,100); g.strokeWeight(Math.max(1.1,pit*0.06)); g.line(ax,ay,bx,by);
  } else if(style==='thread'){
    g.stroke(28,58,22); g.strokeWeight(Math.max(1.1,pit*0.085)); g.line(ax,ay,bx,by);
  } else if(style==='hedge'){
    g.stroke(38,42,52); g.strokeWeight(rw*0.7); g.line(ax,ay,bx,by);
    g.stroke(40,30,66); g.strokeWeight(rw*0.3); g.line(ax,ay,bx,by);
  } else { // dungeon
    g.stroke(28,30,26); g.strokeWeight(rw*0.72); g.line(ax,ay,bx,by);
    g.stroke(30,22,40); g.strokeWeight(rw*0.28); g.line(ax,ay,bx,by);
  }
  g.pop();
}

function computeSolution(){
  const par=S.par;
  const up=c=>{ const a=[]; let g=0; while(c>=0 && g++<N+2){ a.push(c); c=par[c]; } return a; };
  const ancE=up(S.entrance), ancX=up(S.exit);
  const posE=new Map(); ancE.forEach((c,i)=>posE.set(c,i));
  let lca=-1, li=-1;
  for(let i=0;i<ancX.length;i++){ if(posE.has(ancX[i])){ lca=ancX[i]; li=i; break; } }
  let sol;
  if(lca<0) sol=ancE; else sol=ancE.slice(0,posE.get(lca)+1).concat(ancX.slice(0,li).reverse());
  S.sol=sol.map(c=>[centerX(c),centerY(c)]);
  let L=0; S.solLen=[0];
  for(let i=1;i<S.sol.length;i++){ L+=Math.hypot(S.sol[i][0]-S.sol[i-1][0],S.sol[i][1]-S.sol[i-1][1]); S.solLen.push(L); }
  S.solTotal=Math.max(1,L);
}

function carveStep(){
  if(S.stack.length===0){ S.phase='solve'; computeSolution(); return; }
  const cur=S.stack[S.stack.length-1];
  const cx=cur%cols, cy=(cur/cols)|0;
  const nbs=[];
  if(cy>0 && !S.vis[cur-cols]) nbs.push(cur-cols);
  if(cy<rows-1 && !S.vis[cur+cols]) nbs.push(cur+cols);
  if(cx>0 && !S.vis[cur-1]) nbs.push(cur-1);
  if(cx<cols-1 && !S.vis[cur+1]) nbs.push(cur+1);
  if(nbs.length===0){ S.stack.pop(); return; }
  const pick=nbs[(S.rnd()*nbs.length)|0];
  S.vis[pick]=1; S.par[pick]=cur; S.stack.push(pick);
  stampPassage(cur,pick);
}

// ---- advance carve ----
const steps=Math.max(1, Math.round((0.8+P.speed*2.2)*(0.5+intn)+A.bass*5));
for(let s=0;s<steps && S.phase==='carve';s++) carveStep();

// ---- phase progression ----
if(S.phase==='solve'){ S.solveT += (0.014+P.speed*0.02)*(0.6+intn); if(S.solveT>=1){ S.solveT=1; S.phase='hold'; } }
else if(S.phase==='hold'){
  if(S.holdStart==null || K.t<S.holdStart) S.holdStart=K.t;
  const holdDur=4+intn*6;
  if(K.t-S.holdStart>holdDur){ S.phase='dissolve'; S.dissT=0; }
} else if(S.phase==='dissolve'){
  const g=S.buf; g.push(); g.noStroke(); g.fill(gCol[0],gCol[1],gCol[2], 6+P.speed*4); g.rect(0,0,width,height); g.pop();
  S.dissT += 0.02*(0.6+P.speed);
  if(S.dissT>=1){ S.epoch=(S.epoch|0)+1; }
}

// ---- RENDER (shared drift transform) ----
const sc=1.05, dw=width*sc, dh=height*sc;
const dx=-(dw-width)/2 + Math.sin(K.t*0.13)*u*0.007;
const dy=-(dh-height)/2 + Math.cos(K.t*0.11)*u*0.007;
push();
translate(dx,dy); scale(sc);
if(P.alpha<100) tint(0,0,100,P.alpha);
image(S.buf,0,0,width,height);
noTint();

// carve overlays: frontier snake + hot head
if(S.phase==='carve' && S.stack.length){
  const head=S.stack[S.stack.length-1], hx=centerX(head), hy=centerY(head);
  if(S.stack.length>1){ push(); noFill();
    if(glowStyle){ blendMode(ADD); stroke(44,45,100,16*AL); } else { stroke(style==='thread'?353:210, style==='thread'?60:15, style==='thread'?55:100, 30*AL); }
    strokeWeight(pit*0.16); strokeCap(ROUND); strokeJoin(ROUND);
    beginShape(); const st0=Math.max(0,S.stack.length-900); for(let i=st0;i<S.stack.length;i++) vertex(centerX(S.stack[i]),centerY(S.stack[i])); endShape();
    blendMode(BLEND); pop(); }
  push(); const ctx=drawingContext;
  if(glowStyle){ blendMode(ADD); noStroke();
    const pl=0.6+0.4*Math.sin(K.t*6);
    ctx.shadowBlur=18*(0.4+P.energy); ctx.shadowColor='hsla(40,95%,58%,0.95)';
    fill(40,32,100,60*AL); circle(hx,hy,pit*(0.55+0.3*pl));
    fill(48,8,100,92*AL); circle(hx,hy,pit*0.3);
    ctx.shadowBlur=0; blendMode(BLEND);
  } else if(style==='blueprint'){ noFill(); stroke(20,80,100,90*AL); strokeWeight(1.6); rectMode(CENTER); rect(hx,hy,pit*0.7,pit*0.7); rectMode(CORNER);
  } else { noStroke(); fill(353,70,90,92*AL); circle(hx,hy,pit*0.34); }
  pop();
}

// solution overlays: solve reveal + hold
if((S.phase==='solve'||S.phase==='hold') && S.sol && S.sol.length>1){
  const revealLen=(S.phase==='hold')?S.solTotal:clp(S.solveT,0,1)*S.solTotal;
  const solH=(style==='thread')?353:42;
  const sol=S.sol, sl=S.solLen;
  push(); noFill(); strokeCap(ROUND); strokeJoin(ROUND); const ctx=drawingContext;
  if(glowStyle){ blendMode(ADD); ctx.shadowBlur=15*(0.4+P.energy); ctx.shadowColor='hsla('+(style==='thread'?350:42)+',92%,58%,0.9)'; stroke(solH,22,100,72*AL); }
  else if(style==='thread'){ stroke(353,72,80,95*AL); }
  else { stroke(24,85,100,90*AL); }
  strokeWeight(pit*clp(0.16+P.scale*0.08,0.1,0.42));
  beginShape();
  for(let i=0;i<sol.length;i++){
    if(sl[i]<=revealLen){ vertex(sol[i][0],sol[i][1]); }
    else { const t=(revealLen-sl[i-1])/Math.max(1e-3,(sl[i]-sl[i-1])); vertex(sol[i-1][0]+(sol[i][0]-sol[i-1][0])*t, sol[i-1][1]+(sol[i][1]-sol[i-1][1])*t); break; }
  }
  endShape();
  ctx.shadowBlur=0; blendMode(BLEND); pop();
  if(S.phase==='hold'){
    const pos=((K.t*S.solTotal*0.045*(0.4+P.speed))%S.solTotal+S.solTotal)%S.solTotal;
    let i=1; while(i<sl.length && sl[i]<pos) i++;
    if(i<sl.length){ const t=(pos-sl[i-1])/Math.max(1e-3,(sl[i]-sl[i-1]));
      const px=sol[i-1][0]+(sol[i][0]-sol[i-1][0])*t, py=sol[i-1][1]+(sol[i][1]-sol[i-1][1])*t;
      push();
      if(glowStyle||style==='blueprint'){ blendMode(ADD); noStroke(); const c2=drawingContext; c2.shadowBlur=22*(0.4+P.energy); c2.shadowColor='hsla(48,95%,65%,0.95)'; fill(48,10,100,90*AL); circle(px,py,pit*0.5); c2.shadowBlur=0; blendMode(BLEND); }
      else { noStroke(); fill(353,50,100,95*AL); circle(px,py,pit*0.4); }
      pop();
    }
  }
}

// ambient sparkles (glow styles, audio on top)
if(glowStyle && S.vis){
  push(); blendMode(ADD); noStroke();
  const spk=14, tw=A.treble*40;
  for(let i=0;i<spk;i++){
    const idx=(((i*2654435761)>>>0) ^ (Math.floor(K.t*0.7)*40503))%N;
    if(!S.vis[idx]) continue;
    const pl=0.4+0.6*Math.sin(K.t*3+i*1.7);
    fill(46,25,100,(6+pl*10+tw)*AL); circle(centerX(idx),centerY(idx), pit*0.12*(0.5+pl));
  }
  blendMode(BLEND); pop();
}
pop();
